input.command:
N8N_API_KEY="eyJ.[REDACTED-JWT]"
cat > /tmp/create-doc-wf.json <<'EOF'
{
  "name": "TEMP - Create Riverside Doc",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "create-riverside-doc",
        "responseMode": "lastNode",
        "options": {}
      },
      "id": "trigger-1",
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 2,
      "position": [200, 300],
      "webhookId": "create-riverside-doc-webhook"
    },
    {
      "parameters": {
        "method": "POST",
        "url": "https://docs.googleapis.com/v1/documents",
        "authentication": "predefinedCredentialType",
        "nodeCredentialType": "googleDocsOAuth2Api",
        "sendBody": true,
        "specifyBody": "json",
        "jsonBody": "={ \"title\": \"Code Ninjas Riverside KB\" }",
        "options": {}
      },
      "id": "create-1",
      "name": "Create Doc",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [440, 300],
      "credentials": {
        "googleDocsOAuth2Api": {
          "id": "58qerrOCaSjZ51WF",
          "name": "Google Docs account"
        }
      }
    }
  ],
  "connections": {
    "Webhook": { "main": [[{ "node": "Create Doc", "type": "main", "index": 0 }]] }
  },
  "settings": { "executionOrder": "v1" }
}
EOF
curl -s -X POST "https://xprime17.app.n8n.cloud/api/v1/workflows" \
  -H "X-N8N-API-KEY: $N8N_API_KEY" \
  -H "Content-Type: application/json" \
  -d @/tmp/create-doc-wf.json | jq '{id, name, active}'

N8N_API_KEY="eyJ.[REDACTED-JWT]"
# Update temp workflow to share the doc with Scott via Drive API permissions endpoint
cat > /tmp/share-doc-wf.json <<'EOF'
{
  "name": "TEMP - Create Riverside Doc",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "share-riverside-doc",
        "responseMode": "lastNode",
        "options": {}
      },
      "id": "trigger-1",
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 2,
      "position": [200, 300],
      "webhookId": "share-riverside-doc-webhook"
    },
    {
      "parameters": {
        "method": "POST",
        "url": "https://www.googleapis.com/drive/v3/files/1p3vCjF0n9W-4zpi4AUL6HRN3gTpBrkRpxBHUGPLMx-0/permissions?sendNotificationEmail=false",
        "authentication": "predefinedCredentialType",
        "nodeCredentialType": "googleDocsOAuth2Api",
        "sendBody": true,
        "specifyBody": "json",
        "jsonBody": "={ \"role\": \"writer\", \"type\": \"user\", \"emailAddress\": \"scott.james@codeninjas.com\" }",
        "options": {}
      },
      "id": "share-1",
      "name": "Share Doc",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [440, 300],
      "credentials": {
        "googleDocsOAuth2Api": {
          "id": "58qerrOCaSjZ51WF",
          "name": "Google Docs account"
        }
      }
    }
  ],
  "connections": {
    "Webhook": { "main": [[{ "node": "Share Doc", "type": "main", "index": 0 }]] }
  },
  "settings": { "executionOrder": "v1" }
}
EOF
# Deactivate before update
curl -s -X POST "https://xprime17.app.n8n.cloud/api/v1/workflows/9jJ9UFo2ZBXyjvtR/deactivate" -H "X-N8N-API-KEY: $N8N_API_KEY" >/dev/null
curl -s -X PUT "https://xprime17.app.n8n.cloud/api/v1/workflows/9jJ9UFo2ZBXyjvtR" \
  -H "X-N8N-API-KEY: $N8N_API_KEY" -H "Content-Type: application/json" \
  -d @/tmp/share-doc-wf.json | jq '{id, name}'
curl -s -X POST "https://xprime17.app.n8n.cloud/api/v1/workflows/9jJ9UFo2ZBXyjvtR/activate" -H "X-N8N-API-KEY: $N8N_API_KEY" | jq '{active}'
sleep 2
echo "--- share response ---"
curl -s -X POST "https://xprime17.app.n8n.cloud/webhook/share-riverside-doc" -H "Content-Type: application/json" -d '{}' | jq '{id, role, type, emailAddress, error: .error}'

N8N_API_KEY="eyJ.[REDACTED-JWT]"
cat > /tmp/create-doc-wf2.json <<'EOF'
{
  "name": "TEMP - Create KB Doc",
  "nodes": [
    {
      "parameters": {
        "httpMethod": "POST",
        "path": "create-kb-doc",
        "responseMode": "lastNode",
        "options": {}
      },
      "id": "trigger-1",
      "name": "Webhook",
      "type": "n8n-nodes-base.webhook",
      "typeVersion": 2,
      "position": [200, 300],
      "webhookId": "create-kb-doc-webhook"
    },
    {
      "parameters": {
        "method": "POST",
        "url": "https://docs.googleapis.com/v1/documents",
        "authentication": "predefinedCredentialType",
        "nodeCredentialType": "googleDocsOAuth2Api",
        "sendBody": true,
        "specifyBody": "json",
        "jsonBody": "={{ JSON.stringify({ title: $json.body.title }) }}",
        "options": {}
      },
      "id": "create-1",
      "name": "Create Doc",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [440, 300],
      "credentials": {
        "googleDocsOAuth2Api": {
          "id": "58qerrOCaSjZ51WF",
          "name": "Google Docs account"
        }
      }
    },
    {
      "parameters": {
        "method": "POST",
        "url": "=https://www.googleapis.com/drive/v3/files/{{ $json.documentId }}/permissions?sendNotificationEmail=false",
        "authentication": "predefinedCredentialType",
        "nodeCredentialType": "googleDocsOAuth2Api",
        "sendBody": true,
        "specifyBody": "json",
        "jsonBody": "={ \"role\": \"writer\", \"type\": \"user\", \"emailAddress\": \"scott.james@codeninjas.com\" }",
        "options": {}
      },
      "id": "share-1",
      "name": "Share Doc",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [680, 300],
      "credentials": {
        "googleDocsOAuth2Api": {
          "id": "58qerrOCaSjZ51WF",
          "name": "Google Docs account"
        }
      }
    },
    {
      "parameters": {
        "jsCode": "return [{ json: { documentId: $('Create Doc').first().json.documentId, title: $('Create Doc').first().json.title, sharedWith: 'scott.james@codeninjas.com', permissionId: $json.id } }];"
      },
      "id": "respond-1",
      "name": "Respond",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [920, 300]
    }
  ],
  "connections": {
    "Webhook": { "main": [[{ "node": "Create Doc", "type": "main", "index": 0 }]] },
    "Create Doc": { "main": [[{ "node": "Share Doc", "type": "main", "index": 0 }]] },
    "Share Doc": { "main": [[{ "node": "Respond", "type": "main", "index": 0 }]] }
  },
  "settings": { "executionOrder": "v1" }
}
EOF
WF_ID=$(curl -s -X POST "https://xprime17.app.n8n.cloud/api/v1/workflows" -H "X-N8N-API-KEY: $N8N_API_KEY" -H "Content-Type: application/json" -d @/tmp/create-doc-wf2.json | jq -r '.id')
echo "Workflow ID: $WF_ID"
curl -s -X POST "https://xprime17.app.n8n.cloud/api/v1/workflows/$WF_ID/activate" -H "X-N8N-API-KEY: $N8N_API_KEY" >/dev/null
sleep 2
echo "--- Burlington ---"
curl -s -X POST "https://xprime17.app.n8n.cloud/webhook/create-kb-doc" -H "Content-Type: application/json" -d '{"title":"Code Ninjas Burlington KB"}' | jq '{documentId, title, sharedWith, permissionId}'
echo "--- St. Catharines ---"
curl -s -X POST "https://xprime17.app.n8n.cloud/webhook/create-kb-doc" -H "Content-Type: application/json" -d '{"title":"Code Ninjas St. Catharines KB"}' | jq '{documentId, title, sharedWith, permissionId}'
echo "--- WF_ID for cleanup: $WF_ID ---"
